import sys, os, itertools, heapq, random
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "src"))
from data_loader import DATA_FILE_PATH, load_subway_data, build_graph, build_station_to_number
from models import PathfindingConfig
from pathfinding import ShortestPath

data = load_subway_data(DATA_FILE_PATH)
s2n = build_station_to_number(data["stations"])
g = build_graph(data, s2n)
num2name = {v: k for k, v in s2n.items()}

# Brute-force Dijkstra over full (node, line) states WITHOUT transfer cap,
# returning (distance, transfers) Pareto-optimal via exhaustive state search
# with transfers bounded by number of lines.
def brute(src, mode, max_tr=None):
    cap = 30 if max_tr is None else max_tr
    start = (src, None, 0)
    dist = {start: 0.0}
    pq = [(0.0, 0, start)]
    beststation = {}
    while pq:
        d, _, st = heapq.heappop(pq)
        if d > dist.get(st, 1e18) + 1e-9:
            continue
        node, line, tr = st
        # record
        cur = beststation.get(node)
        if cur is None or d < cur[0] - 1e-9:
            beststation[node] = (d, tr)
        for e in g.adj(node):
            ch = 0 if line is None or e.line == line else 1
            ntr = tr + ch
            if ntr > cap:
                continue
            if mode == "least_transfer":
                nd = d + ch * 1_000_000_000 + e.weight
            elif mode == "comprehensive":
                nd = d + e.weight + ch * 1000
            else:
                nd = d + e.weight
            ns = (e.dest, e.line, ntr)
            if nd < dist.get(ns, 1e18) - 1e-9:
                dist[ns] = nd
                heapq.heappush(pq, (nd, ntr, ns))
    return beststation

random.seed(7)
names = list(g.station_lines.keys())
# Compare shortest_distance distances on many random pairs.
bad = 0
for _ in range(300):
    a, b = random.sample(names, 2)
    src, dst = s2n[a], s2n[b]
    sp = ShortestPath(g, src, PathfindingConfig(mode="shortest_distance"))
    ref = brute(src, "shortest_distance")
    if dst in ref:
        got = sp.dist_to.get(dst)
        exp = ref[dst][0]
        if abs(got - exp) > 1e-6:
            print("DIST MISMATCH", a, b, got, exp); bad += 1
    else:
        if dst in sp.dist_to:
            print("SHOULD BE UNREACHABLE", a, b); bad += 1

# Compare least_transfer transfer counts.
for _ in range(200):
    a, b = random.sample(names, 2)
    src, dst = s2n[a], s2n[b]
    sp = ShortestPath(g, src, PathfindingConfig(mode="least_transfer"))
    ref = brute(src, "least_transfer")
    if dst in ref:
        # brute transfer count: recompute by tracking separately
        pass
    # instead: verify least_transfer transfers <= shortest_distance transfers
    sp_sd = ShortestPath(g, src, PathfindingConfig(mode="shortest_distance"))
    if dst in sp.dist_to and dst in sp_sd.dist_to:
        if sp.get_transfer_count(dst) > sp_sd.get_transfer_count(dst):
            print("LT WORSE THAN SD", a, b, sp.get_transfer_count(dst), sp_sd.get_transfer_count(dst)); bad += 1

# max_transfers enforcement on random pairs
for _ in range(200):
    a, b = random.sample(names, 2)
    src, dst = s2n[a], s2n[b]
    mt = random.randint(0, 3)
    sp = ShortestPath(g, src, PathfindingConfig(max_transfers=mt))
    if dst in sp.dist_to:
        tc = sp.get_transfer_count(dst)
        if tc > mt:
            print("MAX_TRANSFERS VIOLATED", a, b, mt, tc); bad += 1

# path_with_edges invariants across all pairs for one source
src = s2n["Xidan"]
sp = ShortestPath(g, src)
for n, num in s2n.items():
    if num in sp.dist_to:
        p, e = sp.path_with_edges(num)
        if len(e) != len(p) - 1 or p[0] != src or p[-1] != num:
            print("PATH INVARIANT FAIL", n); bad += 1
        # every edge connects consecutive stations
        for i, ed in enumerate(e):
            if ed.source != p[i] or ed.dest != p[i + 1]:
                print("EDGE CHAIN FAIL", n); bad += 1
        if abs(sum(x.weight for x in e) - sp.dist_to[num]) > 1e-6:
            print("DIST SUM FAIL", n); bad += 1

print("bad =", bad)
print("ALL GOOD" if bad == 0 else "PROBLEMS FOUND")

