"""Core data structures for the Beijing Subway fare calculation system.

This module provides the low level building blocks used by the rest of the
system:

* :class:`Edge` -- a directed edge between two stations on a given line.
* :class:`Graph` -- an undirected weighted graph represented with adjacency
  lists.
* :class:`MinPQ` -- a binary-heap based minimum priority queue used to keep
  Dijkstra's algorithm at ``O((V + E) log V)``.
* :class:`PathfindingConfig` -- configuration object describing the requested
  path query mode and constraints.
"""

from __future__ import annotations

from typing import Dict, Hashable, List, Optional, Tuple


class Edge:
    """A directed edge of the subway network.

    ``source`` and ``dest`` are station numbers (integers), ``weight`` is the
    distance in meters and ``line`` is the name of the line the edge belongs
    to. All four attributes are readable and two edges compare equal when all
    four attributes are equal.
    """

    __slots__ = ("source", "dest", "weight", "line")

    def __init__(self, source: int, dest: int, weight: float, line: str) -> None:
        self.source = source
        self.dest = dest
        self.weight = weight
        self.line = line

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Edge):
            return NotImplemented
        return (
            self.source == other.source
            and self.dest == other.dest
            and self.weight == other.weight
            and self.line == other.line
        )

    def __hash__(self) -> int:
        return hash((self.source, self.dest, self.weight, self.line))

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return (
            f"Edge(source={self.source!r}, dest={self.dest!r}, "
            f"weight={self.weight!r}, line={self.line!r})"
        )

    def reversed(self) -> "Edge":
        """Return the edge travelling in the opposite direction."""
        return Edge(self.dest, self.source, self.weight, self.line)


class Graph:
    """A weighted undirected graph stored as an adjacency list.

    Internally every undirected edge is represented by two directed
    :class:`Edge` objects so that Dijkstra's algorithm can traverse it in both
    directions.
    """

    def __init__(self) -> None:
        self._adj: Dict[int, List[Edge]] = {}
        # Mapping from station name to the list of line names serving it.
        self.station_lines: Dict[str, List[str]] = {}

    # ------------------------------------------------------------------
    # Building blocks
    # ------------------------------------------------------------------
    def _ensure_node(self, node: int) -> None:
        if node not in self._adj:
            self._adj[node] = []

    def add_edge(self, edge: Edge) -> None:
        """Add an undirected edge (both traversal directions)."""
        self._ensure_node(edge.source)
        self._ensure_node(edge.dest)
        self._adj[edge.source].append(edge)
        self._adj[edge.dest].append(edge.reversed())

    def set_station_lines(self, station_name: str, lines: List[str]) -> None:
        """Record the line names serving ``station_name``."""
        self.station_lines[station_name] = list(lines)

    # ------------------------------------------------------------------
    # Queries
    # ------------------------------------------------------------------
    def adj(self, node: int) -> List[Edge]:
        """Return the edges leaving ``node`` (empty list when unknown)."""
        return self._adj.get(node, [])

    def nodes(self) -> List[int]:
        """Return every node currently present in the graph."""
        return list(self._adj.keys())

    def __contains__(self, node: object) -> bool:
        return node in self._adj

    def __len__(self) -> int:
        return len(self._adj)


class MinPQ:
    """A minimum priority queue backed by a binary heap.

    Supports the three operations required by Dijkstra's algorithm:
    :meth:`insert`, :meth:`del_min` and :meth:`is_empty`.
    """

    def __init__(self) -> None:
        # Each entry is a ``(priority, sequence, item)`` tuple. The monotonically
        # increasing ``sequence`` breaks ties deterministically and avoids
        # comparing items that are not orderable.
        self._heap: List[Tuple[float, int, Hashable]] = []
        self._counter = 0

    def insert(self, item: Hashable, priority: float) -> None:
        """Insert ``item`` with the given ``priority``."""
        entry = (priority, self._counter, item)
        self._counter += 1
        self._heap.append(entry)
        self._sift_up(len(self._heap) - 1)

    def del_min(self) -> Hashable:
        """Remove and return the item with the smallest priority."""
        if not self._heap:
            raise IndexError("del_min from an empty priority queue")
        heap = self._heap
        smallest = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            self._sift_down(0)
        return smallest[2]

    def is_empty(self) -> bool:
        """Return ``True`` when the queue holds no items."""
        return not self._heap

    def __len__(self) -> int:
        return len(self._heap)

    # ------------------------------------------------------------------
    # Heap helpers
    # ------------------------------------------------------------------
    def _less(self, i: int, j: int) -> bool:
        a = self._heap[i]
        b = self._heap[j]
        # ``item`` is never compared: sequence numbers are unique.
        return (a[0], a[1]) < (b[0], b[1])

    def _swap(self, i: int, j: int) -> None:
        self._heap[i], self._heap[j] = self._heap[j], self._heap[i]

    def _sift_up(self, k: int) -> None:
        while k > 0:
            parent = (k - 1) // 2
            if self._less(k, parent):
                self._swap(k, parent)
                k = parent
            else:
                break

    def _sift_down(self, k: int) -> None:
        n = len(self._heap)
        while True:
            left = 2 * k + 1
            right = left + 1
            smallest = k
            if left < n and self._less(left, smallest):
                smallest = left
            if right < n and self._less(right, smallest):
                smallest = right
            if smallest == k:
                break
            self._swap(k, smallest)
            k = smallest


class PathfindingConfig:
    """Configuration for a path query.

    Attributes:
        mode: one of ``"shortest_distance"``, ``"least_transfer"`` or
            ``"comprehensive"``.
        max_transfers: maximum number of transfers allowed, or ``None`` for no
            limit.
        preferred_lines: list of line names that should be preferred when they
            exist along the route.
    """

    VALID_MODES = ("shortest_distance", "least_transfer", "comprehensive")

    def __init__(
        self,
        mode: str = "shortest_distance",
        max_transfers: Optional[int] = None,
        preferred_lines: Optional[List[str]] = None,
    ) -> None:
        if mode not in self.VALID_MODES:
            raise ValueError(
                f"Unknown mode {mode!r}; expected one of {self.VALID_MODES}"
            )
        self.mode = mode
        self.max_transfers = max_transfers
        self.preferred_lines = list(preferred_lines) if preferred_lines else []

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return (
            f"PathfindingConfig(mode={self.mode!r}, "
            f"max_transfers={self.max_transfers!r}, "
            f"preferred_lines={self.preferred_lines!r})"
        )

