"""Core data structures for the Beijing Subway fare calculation system.

This module implements the graph primitives required by the PRD:

* :class:`Edge` -- a directed weighted edge between two stations.
* :class:`Graph` -- a weighted undirected graph stored as adjacency lists.
* :class:`MinPQ` -- a binary-heap minimum priority queue used by Dijkstra.
* :class:`PathfindingConfig` -- options controlling a path query.
"""

from __future__ import annotations

import heapq
from typing import Dict, Iterable, List, Optional


class Edge:
    """A directed edge of the subway graph.

    ``source`` and ``dest`` are station numbers (integers), ``weight`` is the
    distance in meters and ``line`` is the name of the line the edge belongs
    to.  All four attributes are exposed as plain readable attributes.
    """

    __slots__ = ("source", "dest", "weight", "line")

    def __init__(self, source: int, dest: int, weight: float, line: str) -> None:
        self.source = source
        self.dest = dest
        self.weight = weight
        self.line = line

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Edge):
            return NotImplemented
        return (
            self.source == other.source
            and self.dest == other.dest
            and self.weight == other.weight
            and self.line == other.line,
        )

    def __hash__(self) -> int:
        return hash((self.source, self.dest, self.weight, self.line))

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return (
            f"Edge(source={self.source!r}, dest={self.dest!r}, "
            f"weight={self.weight!r}, line={self.line!r})"
        )


class Graph:
    """A weighted undirected graph represented with adjacency lists.

    Although every stored :class:`Edge` is directed, :meth:`add_edge` records
    both directions so the graph behaves as undirected: an edge can be
    traversed from ``source`` to ``dest`` and from ``dest`` to ``source``.
    """

    def __init__(self) -> None:
        self._adj: Dict[int, List[Edge]] = {}
        self.station_lines: Dict[str, List[str]] = {}

    def add_edge(self, edge: Edge) -> None:
        """Add ``edge`` and its reverse, keeping the graph undirected."""
        self._adj.setdefault(edge.source, []).append(edge)
        reverse = Edge(edge.dest, edge.source, edge.weight, edge.line)
        self._adj.setdefault(edge.dest, []).append(reverse)

    def set_station_lines(self, station_name: str, lines: Iterable[str]) -> None:
        """Record the line names serving ``station_name``."""
        self.station_lines[station_name] = list(lines)

    def adj(self, node: int) -> List[Edge]:
        """Return the edges leaving ``node`` (an empty list if unknown)."""
        return self._adj.get(node, [])

    def nodes(self) -> List[int]:
        """Return every node that currently takes part in an edge."""
        return list(self._adj.keys())

    def add_node(self, node: int) -> None:
        """Ensure ``node`` exists in the graph even without incident edges."""
        self._adj.setdefault(node, [])


class MinPQ:
    """A minimum priority queue backed by a binary heap.

    Items are inserted with :meth:`insert` together with a numeric priority;
    :meth:`del_min` removes and returns the item with the smallest priority.
    """

    def __init__(self) -> None:
        self._heap: List[tuple] = []
        self._counter = 0

    def is_empty(self) -> bool:
        return not self._heap

    def insert(self, item, priority: float) -> None:
        # ``_counter`` keeps insertion order stable when priorities tie, which
        # makes the search deterministic across runs.
        heapq.heappush(self._heap, (priority, self._counter, item))
        self._counter += 1

    def del_min(self):
        if not self._heap:
            raise IndexError("del_min from an empty priority queue")
        return heapq.heappop(self._heap)[2]

    def __len__(self) -> int:
        return len(self._heap)


class PathfindingConfig:
    """Options controlling how a shortest-path query is executed.

    ``mode`` selects the optimisation goal, ``max_transfers`` optionally caps
    the number of line changes and ``preferred_lines`` lists line names that
    should be favoured when they appear along the route.
    """

    MODES = ("shortest_distance", "least_transfer", "comprehensive")

    def __init__(
        self,
        mode: str = "shortest_distance",
        max_transfers: Optional[int] = None,
        preferred_lines: Optional[Iterable[str]] = None,
    ) -> None:
        if mode not in self.MODES:
            raise ValueError(
                f"unknown mode {mode!r}; expected one of {', '.join(self.MODES)}"
            )
        self.mode = mode
        self.max_transfers = max_transfers
        self.preferred_lines: List[str] = list(preferred_lines or [])

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return (
            f"PathfindingConfig(mode={self.mode!r}, "
            f"max_transfers={self.max_transfers!r}, "
            f"preferred_lines={self.preferred_lines!r})"
        )

